201	function processChunk(
202	  ws: WebSocket,
203	  session: ChatSession,
204	  state: StreamState,
205	  parser: ThinkingTagParser,
206	  chunk: MessageChunk
207	): void {
208	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
209	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
210	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
211	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
212	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
213	}
214	
215	function processTextChunk(
216	  ws: WebSocket,
217	  session: ChatSession,
218	  state: StreamState,
219	  parser: ThinkingTagParser,
220	  text: string
221	): void {
222	  const segments = parser.push(text);
223	  for (const segment of segments) {
224	    handleTextSegment(ws, session, state, segment);
225	  }
226	}
227	
228	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
229	  if (segment.type === 'thinking') {
230	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
231	    return;
232	  }
233	  commitAndClear(ws, session, state, 'thinkingIndex');
234	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
235	}
236	
237	function streamSegment(
238	  ws: WebSocket,
239	  session: ChatSession,
240	  state: StreamState,
241	  key: StateIndexKey,
242	  createEntry: EntryFactory,
243	  content: string
244	): void {
245	  const isNew = initSegment(session, state, key, createEntry);
246	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
247	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
248	  appendDelta(session, state[key]!, content);
249	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
250	}
251	
252	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
253	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
254	  markSuppressed(session, index);
255	  sendSkip(ws, index);
256	}
257	
258	function markSuppressed(session: ChatSession, index: number): void {
259	  const entry = session.entries[index];
260	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
261	}
262	
263	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
264	  if (state[key] !== null) return false;
265	  state[key] = appendEntry(session, createEntry());
266	  return true;
267	}
268	
269	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
270	  const index = state[key];
271	  if (index === null) return;
272	
273	  commitEntry(session, index);
