async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string; sessionId: string}}
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  const sessions = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
  const response = {
    type: 'session_list' as const,
    sessions: sessions.map(s => ({
      sessionId: s.sessionId,
      createdAt: typeof s.createdAt === 'string' ? s.createdAt : s.createdAt.toISOString(),
      updatedAt: typeof s.updatedAt === 'string' ? s.updatedAt : s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    })),
  };
  sendJson(ws, response);
}

