function setupListSessionsTest(listFor: (userId: string | number, options?: unknown) => unknown): {
  sent: OutgoingMessage[];
  ws: WebSocket;
  orchestrator: ChatOrchestrator;
  session: ChatSession;
  handle: Function;
} {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const inner = new InMemorySessionStore();
  const sessionStore = {...delegatingTo(inner), listFor};
  const handle = createMessageHandler(orchestrator, sessionStore);
  return {sent, ws, orchestrator, session, handle};
}

describe('list_sessions message handler', () => {
  it('calls listFor on sessionStore when receiving a list_sessions message', async () => {
    const listFor = jest.fn(async () => []);
    const {sent, ws, session, handle} = setupListSessionsTest(listFor);

    await handle(ws, session, {type: 'list_sessions', limit: 10});

    expect(listFor).toHaveBeenCalledWith('u1', {limit: 10, before: undefined});
  });

  it('sends SERVER_ERROR and logs error when listFor rejects', async () => {
    const logs: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: () => undefined,
      error: (category: string, message: string, fields?: Record<string, unknown>) => {
        logs.push({level: 'error', category, message, fields});
      },
    });
    const {sent, ws, session, handle} = setupListSessionsTest(() => Promise.reject(new Error('database offline')));

    await handle(ws, session, {type: 'list_sessions'});

